package com.bank.analytics;

import java.util.ArrayDeque;
import java.util.Deque;

// For each day, how many days until a strictly higher value appears.
public class DaysToWarmerFinder {

    public int[] daysUntilHigher(int[] values) {
        int n = values.length;
        int[] answer = new int[n];          // defaults to 0 (no higher day)
        Deque<Integer> stack = new ArrayDeque<>(); // indices, decreasing values

        for (int i = 0; i < n; i++) {
            // Current value resolves every smaller pending day.
            while (!stack.isEmpty() && values[i] > values[stack.peek()]) {
                int prevDay = stack.pop();
                answer[prevDay] = i - prevDay; // gap in days
            }
            stack.push(i);
        }
        // Indices left on the stack keep their default 0.
        return answer;
    }
}
