package com.bank.analytics;

import java.util.Arrays;
import java.util.logging.Logger;

// Produces the "days to recovery" dashboard metric.
public class SentimentAnalyticsService {

    private static final Logger log = Logger.getLogger(SentimentAnalyticsService.class.getName());
    private final DaysToWarmerFinder finder;

    public SentimentAnalyticsService(DaysToWarmerFinder finder) {
        this.finder = finder;
    }

    public int[] daysToRecovery(int[] sentimentSeries) {
        int[] waits = finder.daysUntilHigher(sentimentSeries);
        log.info(() -> "Sentiment " + Arrays.toString(sentimentSeries)
                + " days-to-recovery = " + Arrays.toString(waits));
        return waits;
    }
}
