package com.bank.analytics;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DaysToWarmerDemo {

    private static final Logger log = Logger.getLogger(DaysToWarmerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Sentiment Days-to-Recovery");
        SentimentAnalyticsService service =
                new SentimentAnalyticsService(new DaysToWarmerFinder());

        int[] sentiment = {73, 74, 75, 71, 69, 72, 76, 73};
        // expected waits: [1,1,4,2,1,1,0,0]
        service.daysToRecovery(sentiment);
    }
}
